from build_program import ROOT, write, table
import json

# Each authored row: kind | question | spoken answer | deeper example |
# incorrect answer | follow-up | full-credit discriminator.
groups=[]
def add(topic, track, module, refs, assumptions, rows):
    parsed=[]
    for line in rows.strip().splitlines():
        parts=[x.strip() for x in line.split('|')]
        assert len(parts)==7,(topic,len(parts),line)
        parsed.append(parts)
    assert len(parsed)==10,(topic,len(parsed))
    groups.append((topic,track,module,refs,assumptions,parsed))

add('C objects and ownership','All','M01','R01','ISO C11; valid live pointer regions are caller preconditions.',r'''
C|Implement a bounded big-endian 16-bit read.|Validate pointer/output and offset before subtracting remaining size; assemble two unsigned bytes; commit output only on success.|Check offset>size first, then size-offset<2. Test offsets 0, size-2, size-1 and SIZE_MAX. See E-M01 for the separate complete solution.|Testing offset+2<=size can wrap; casting to uint16_t pointer assumes alignment and endian.|What if output aliases input?|Bounds proof plus unchanged-output test.
C|Write a checked allocation-size helper.|Reject multiplication when b is nonzero and a>SIZE_MAX/b, then assign a*b.|Zero factors are valid zero-size results. Keep output unchanged on overflow; the caller still decides whether zero allocation is meaningful. B01 eu_size_mul is the implementation.|Multiply then compare against SIZE_MAX.|How does subsequent header-size addition change the check?|Pre-multiplication check and explicit zero/output semantics.
C|Copy a bounded string into a fixed buffer with an explicit policy.|Accept source length separately, reserve one byte for the terminator and reject insufficient capacity before copying.|For reject-on-truncation, require cap>0 and source_length<cap. Only copy a promised readable region; source length cannot validate arbitrary memory. Specify overlap policy or use memmove.|Calling strlen on untrusted unterminated bytes.|How do you represent embedded zero bytes?|Distinguish string from byte span and state truncation/overlap contract.
C|Design an ownership-safe function returning parsed data.|Return copied fields in caller-owned output, or explicitly document a borrowed view and its lifetime.|B01 copies at most 64 payload bytes. A zero-copy view can be useful but must not outlive the receive buffer or survive its reuse without ownership transfer.|Return a pointer to an automatic local array.|How would a buffer pool change ownership?|Identify owner, lifetime, valid bounds and cleanup on every return.
T|What does const guarantee?|It restricts modification through a qualified access path; it does not confer ownership or synchronization.|A const byte pointer can still observe data changed through another legal non-const alias. A const pointer object and pointer-to-const protect different operations.|Const means stored in ROM or immutable everywhere.|Can casting away const ever be legal?|Separate access qualification from the actual object's definition.
C|Implement a resource cleanup path after several allocations.|Track acquired resources and unwind in reverse dependency order; one cleanup section can keep failure paths consistent.|Initialize handles to invalid values. If buffer allocation follows opening a file, free the buffer before closing dependent context. Do not retry close blindly after an ambiguous platform error.|Return immediately on every error without releasing earlier resources.|When is goto cleanup preferable to nested conditionals?|No leaks, double free or dependency inversion on each injected failure.
T|Explain automatic, static and allocated storage duration.|Automatic objects last for their block activation, static objects for program execution, and allocated objects until release.|Scope governs name visibility; lifetime governs valid object access. A static local has block scope and program lifetime. Stack/heap terminology alone does not describe C's rules.|A pointer keeps its pointee alive.|Can a returned struct contain a dangling pointer?|Distinguish scope, duration, linkage and ownership.
O|Predict int i=1; int j=i++ + i++; under C11.|The modifications are unsequenced, so the behavior is undefined; there is no portable numeric result.|Split the intended updates into separate full expressions. One compiler result is an observation, not an answer guaranteed by the language.|It always prints 3 or depends only on left-to-right evaluation.|How does independent argument evaluation differ?|Correct behavior category and a well-defined rewrite.
C|Implement overlapping byte movement safely.|Use memmove for potentially overlapping regions, or choose copy direction after a valid same-object range analysis.|memcpy requires nonoverlapping regions. A manual reverse loop must avoid unsigned underflow at zero length. Library use is often clearer than recreating optimized primitives.|memcpy is safe because both pointers are valid.|How would you test forward/backward overlap?|Correct overlap policy and zero-length boundaries.
T|How do arrays differ from pointers at function boundaries?|A real array has a compile-time object size; array parameters adjust to pointers and lose that size information.|sizeof local_array measures its bytes, whereas sizeof parameter measures a pointer. Pass count or an explicit span contract. Pointer arithmetic remains bounded by the original array.|sizeof parameter gives original array capacity.|What does a static array parameter annotation promise?|Explain adjustment and caller size obligations.
''')

add('Integers, representation and behavior','All','M01','R01; R08','C11; widths and plain-char signedness must be stated.',r'''
C|Create a checked single-bit uint32_t mask.|Reject position>=32 and shift UINT32_C(1) by the validated count.|Use a valid output object and leave it unchanged on failure. Test positions 0,31,32 and null output. B01 eu_bit32 supplies a reference.|Use signed 1<<31 unconditionally.|What changes if uint32_t is unavailable?|Unsigned operand, valid shift bound and explicit output semantics.
C|Replace only selected bits of an integer.|Compute (old & ~mask) combined by bitwise OR with (value & mask).|The second mask prevents value from modifying unrelated bits. This is for ordinary integers, not universally safe register read-modify-write. See B01 eu_bits_update32.|OR value into old without clearing the field.|What about write-one-to-clear registers?|Preserve all outside-mask bits and identify MMIO qualification.
C|Decode a signed 16-bit sensor sample portably.|Assemble an unsigned 16-bit value, then map values above INT16_MAX to their intended negative numeric value in a wider signed type.|For two's-complement wire encoding, int32_t signed_value = u<=32767 ? (int32_t)u : (int32_t)u-65536. Avoid relying on an out-of-range unsigned-to-signed conversion under C11.|Cast an unaligned byte pointer to int16_t pointer.|How would a 12-bit left-aligned sample change decoding?|Correct sign extension based on specified wire bits, not host layout.
C|Parse an unsigned decimal CLI argument robustly.|Use a checked conversion, reject a leading minus for an unsigned contract, detect overflow and require full consumption.|With strtoul, reset/check errno, end pointer and destination maximum; reject empty input and undesired whitespace/sign policy explicitly. Do not silently truncate to a smaller type.|atoi followed by a range check catches every error.|How do you reject 12abc or a value above UINT32_MAX?|Full syntax/range/error distinction.
O|What is the result of comparing int n=-1 with size_t cap=8?|Under common selected data models n converts to an unsigned size type, so n<cap is false; explain the actual types first.|Validate n>=0 before casting to size_t. The surprising result arises from the usual arithmetic conversions, not a runtime bounds check.|Negative values are always less than positive values regardless of types.|How do integer rank and representability affect the rule?|State implementation assumptions and safe comparison order.
C|Test whether a positive integer is a power of two.|Require n!=0 and test that n & (n-1) is zero using an unsigned type.|The zero guard matters because zero also satisfies the second expression. Do not assume every ring must use power-of-two capacity; B01 deliberately does not.|Zero is a power of two.|How does this enable index masking?|Zero/one/high-bit tests and explain representation tradeoff.
T|Why should a protocol not serialize a native struct?|Padding, alignment, endian and ABI choices are not a wire contract.|Encode fields at specified byte offsets and validate lengths. Packed layout alone does not specify byte order or make unaligned field access safe on every architecture.|Packed guarantees portability and interoperability.|How would you evolve the wire version?|Separate representation from semantic schema and compatibility.
C|Add two size values with overflow detection.|Reject a>SIZE_MAX-b before computing a+b, with b already a valid size_t.|This is needed when adding a header after checked payload multiplication. Multiplication safety does not imply total allocation safety. Keep output unchanged on rejection.|Check whether result is negative.|How would signed addition require different checks?|Bound before addition and test SIZE_MAX boundaries.
O|Classify char c=255 and signed right shift under C11.|The conversion depends on plain-char signedness/range and implementation rules; right shift of a negative signed value is implementation-defined.|State compiler/target before describing an observed result. Prefer unsigned bit manipulation and explicit numeric reconstruction for protocol work.|All C implementations use signed char and arithmetic shift.|Which behaviors are undefined rather than implementation-defined?|Do not invent one universal representation outcome.
T|What do alignment and effective type protect?|They constrain which addresses and access types may be used for objects; violating them can invalidate an otherwise plausible byte cast.|A correctly sized byte array is not automatically a suitably aligned uint32_t object. Use byte assembly or copying into a declared integer, then convert endian.|It works on x86, so the cast is portable.|Does memcpy solve endian conversion?|Identify alignment, alias/type and byte-order concerns separately.
''')

add('Data structures, parsing and state machines','All','M01','B01; R05','B01 is single-context or externally locked; packet CRC is not authentication.',r'''
C|Implement a full-capacity byte ring.|Use head, tail and count with indexes bounded by capacity; push/pop update exactly one byte and wrap index.|Empty is count=0, full count=capacity. Caller owns backing storage. Test against a simple shifting-array model rather than duplicating ring internals.|Mix reserved-slot full test with count-based capacity.|What changes for multiple producers?|Correct invariants, full/empty behavior and external serialization contract.
C|Implement ring peek without mutation.|Validate ring/output, return empty without changing output, otherwise read storage[tail].|Do not pop then push: that can reorder a full queue and exposes temporary state. Compare metadata before/after and test wrapped/capacity-one cases.|Peek advances tail then restores only count.|What is the newest element's index?|No state change and correct oldest-byte selection.
C|Implement CRC-16 for a precisely named variant.|Specify polynomial, initial value, reflection, final XOR and byte coverage; update a bounded unsigned accumulator.|B01 uses poly 0x1021, init 0xFFFF, no reflection/xorout, with 123456789 checking to 0x29B1. A polynomial alone does not identify a CRC variant.|Any CRC called CRC16 interoperates.|Why can an attacker modify a CRC-protected frame?|Parameter completeness and known-vector test.
C|Implement exact-frame validation with an owned result.|Check minimum/maximum size, magic/version, declared length and checksum before copying into a local result and committing it.|For B01 require N=L+8 and L<=64. Reject trailing bytes. Stream accumulation is a separate layer, so parser failures do not partially consume a stream invisibly.|Copy declared payload first, then validate its length.|Why leave output unchanged on failure?|Each read/copy is justified by an earlier bound.
C|Design a bounded stream framing state machine.|Accumulate a fixed header, validate declared size, collect body, verify, deliver and resume; timeout/noise recovery is bounded.|Track consumed bytes and monotonic deadline. A malformed header must either consume input or reset with progress; prevent an infinite retry on the same byte.|Assume each read returns one whole packet.|How do you handle overlapping magic bytes?|Bounded memory, progress and explicit recovery semantics.
T|When choose an array, linked list or ring?|Choose from access pattern, bounds, locality and ownership costs; small embedded queues often favor fixed arrays/rings.|A linked list supports flexible insertion but needs allocation/lifetime rules and poor locality can dominate. O(1) insertion does not imply predictable end-to-end timing.|Linked lists are always faster because insertion is O(1).|What changes in interrupt context?|Tie data structure to workload and resource constraints.
C|Implement a finite-state machine for a timed request.|Use explicit states and events, one owner, a monotonic deadline and defined timeout/retry limits.|Example IDLE→WAIT_ACK→COMPLETE or TIMEOUT. Match replies by session/sequence and make duplicate handling explicit; do not recursively retry forever.|A boolean busy flag is enough to describe all errors.|How do reset and cancellation change the state graph?|Every event/state combination has a defined transition or rejection.
C|Implement a callback dispatch table safely.|Use a correctly typed function pointer array, validate an external index and handle missing callbacks.|Do not cast unrelated function pointer types to silence a compiler error. The registration/lifetime and execution context of callback data remain part of the interface.|Any function pointer can be cast and called safely.|Who owns callback context during unregister?|Signature/index/lifetime correctness.
C|Parse a type-length-value buffer defensively.|At each step require header bytes, validate value_length<=remaining-header, process/skip known or unknown types and advance by a safe amount.|Decide duplicate-tag and unknown-tag policy. Validate before advancing; avoid adding untrusted lengths before overflow checks. Test zero-length entries and truncated final values.|Trust the outer length to make every inner field safe.|How do nested containers affect maximum work?|Bounded progress and independent validation at each level.
T|Why are complexity and timing different claims?|Big-O describes growth under a model; deadlines require concrete costs and interference bounds.|B01 queue operations are O(1), but cache misses, interrupts and scheduling still affect elapsed time. Report measurements with workload and target rather than turning O(1) into a deadline guarantee.|Constant time means constant nanoseconds.|How would you build a deadline argument?|Separate algorithmic work, observed latency and defensible upper bound.
''')

add('Tools, ABI, C++ and workflow','All','M02','R18; R19','Linux ELF examples; C++ behavior follows the chosen standard/toolchain and target policy.',r'''
T|Explain compilation versus linking.|Compilation translates each translation unit to object code; linking resolves symbols and lays out a complete image with libraries.|An undefined reference can come from a missing definition, omitted object, C/C++ linkage mismatch or library order. Inspect symbols and the exact link line instead of changing includes blindly.|An include file causes its implementation to be linked.|How do static and shared libraries differ?|Differentiate declarations, definitions, object selection and runtime loading.
D|A declaration is visible but linking reports undefined reference. What next?|Inspect the expected symbol, object/library definitions and exact link inputs; check C++ name mangling and archive order.|Use nm/readelf equivalents on the actual target objects. Headers can declare a function whose source was never built. Record target architecture before comparing similarly named libraries.|Add more header includes until the linker succeeds.|What if the symbol exists only as local/static?|Evidence-driven symbol-resolution diagnosis.
C|Write a minimal Make rule that rebuilds after header changes.|Declare source/header prerequisites, compile with explicit flags and use a generated output directory prerequisite.|B01 Makefile is a small complete example. Larger projects can generate dependencies with compiler -MMD/-MP; command/flag changes also need a consistent build strategy.|Only .c timestamps affect outputs.|Why can a stale object hide an ABI mismatch?|Correct dependencies plus clean-build verification.
T|What is an ABI?|It is the binary interface contract for calling conventions, type layout, registers, symbols and related platform rules.|Two files can agree in C declarations but disagree in float ABI, struct packing or architecture. Inspect compiler target/options and binary metadata. Source API compatibility does not ensure binary compatibility.|ABI is just the list of function names.|How does LLP64 differ from LP64?|Connect a concrete layout/call mismatch to toolchain evidence.
T|How do linker scripts and map files help firmware?|A linker script maps sections into target memory; a map file shows actual placement, size and symbol allocation.|Startup must copy initialized .data from load location and zero .bss at run location. Verify stack/heap/vector placement against the MCU memory map.|The linker automatically knows every board's memory layout.|What is load address versus execution address?|Explain sections, memory regions and startup relationship.
T|What should a small code review prioritize?|Correctness contracts, resource lifetime, concurrency, error paths and tests before style preferences.|Walk one successful operation, one malformed input and each partial acquisition/cleanup path. A tidy diff can still introduce asynchronous use-after-free.|Style compliance proves maintainability and correctness.|How would you reduce a review's uncertainty?|Name concrete failure cases and evidence, not generic praise.
T|How does C++ RAII help embedded software?|It binds resource release to object lifetime, reducing manual cleanup errors when ownership is clear.|A file/lock wrapper can release on all exits. Consider move-only ownership, exception policy, allocation budget and target runtime support. It does not solve dangling borrowed references or device ordering.|RAII requires heap allocation or garbage collection.|How would you represent a unique DMA buffer owner?|Tie destructor/lifetime semantics to explicit ownership.
C|Design a move-only file-descriptor owner.|Store one valid descriptor or invalid sentinel, close it once in destruction, delete copying and transfer ownership on move.|Move assignment must release its current resource before taking another and leave the source invalid; handle self-move policy. A complete implementation depends on the selected error/destructor policy.|Copy the integer descriptor and let both destructors close it.|When should you dup instead of transfer?|Exactly-once ownership and valid moved-from state.
D|A build passes locally but fails in CI. How investigate?|Compare pinned sources, tool versions, environment, clean state and exact failing command; reproduce in the CI environment.|Case-sensitive paths, undeclared dependencies, generated files and host-library leakage are candidates. A clean build is a discriminating test, not proof that CI is wrong.|Disable warnings or retry until green.|How would you prevent the same class of failure?|Identify and declare the actual missing input/assumption.
T|What belongs in an engineering commit and automation script?|A focused change, reason, relevant verification and reproducible commands with explicit failures.|Scripts should propagate nonzero exit codes and avoid swallowing stderr. Keep secrets/generated binaries out of source history. Review the diff before committing; tests run on one host have a limited claim.|A script printing PASS means the command succeeded.|How do you link logs to a source revision?|Traceability and truthful command status.
''')

add('Linux files, processes and service behavior','EL/KD','M03','R20; R21; R22','Linux userspace; proc/sys output and service policies vary by target.',r'''
T|What distinguishes process and thread?|A process provides an address-space/resource context; threads within it share memory while retaining their own execution state and stack.|File-descriptor tables and signal details have specific sharing rules. Shared memory makes thread coordination necessary; separate processes still communicate through explicit IPC.|Threads have separate heaps by default.|When choose process isolation over threads?|Discuss shared resources, failure isolation and communication cost.
D|A PID disappears while your inspector reads /proc. Is this a bug?|It is an expected race in a dynamic system; handle missing entries and report a partial observation.|PID reuse can also make two reads refer to different process lifetimes. Record start identity where needed; do not claim a coherent global snapshot from directory enumeration.|Retry forever until every discovered PID is readable.|How would you test without depending on timing luck?|Explicit race policy and deterministic fixture/process lifecycle test.
T|What do file permissions and umask control?|Permission bits govern access subject to identity and other policy; umask removes permissions from newly created objects.|Directory read/search/write differ from file permissions. ACLs, capabilities, mount and security-module policies may further affect access. Never infer a permission problem from one chmod guess.|chmod 777 is the right default fix.|Why does execute/search permission matter on a directory?|Least-privilege explanation and actual access-path checks.
T|Explain /proc, /sys and /dev.|proc exposes process/kernel observations, sysfs exposes kernel object attributes, and /dev contains device nodes used through subsystem interfaces.|A device node is an entry point, not stored hardware data. udev or other device management can create policy/names from kernel events; minimal images may use devtmpfs/mdev instead.|Every file under /dev is a regular disk file.|What creates a device node on a minimal image?|Connect discovery, kernel interface and userspace policy.
T|What happens during fork and exec?|fork creates a child process context; exec replaces a process image while retaining selected resources such as descriptors not close-on-exec.|Close inherited pipe ends and set close-on-exec deliberately. Error reporting around exec should not assume the parent's multithreaded library state is safe for arbitrary child calls.|exec creates a new PID automatically.|Why use posix_spawn in some designs?|Resource inheritance and exec-failure cleanup.
D|Your child process becomes a zombie. What happened?|The child exited but its status has not been collected by a parent or appropriate reaper.|Use wait/waitpid with a robust signal/event design. A zombie consumes an entry/status, not an actively executing CPU thread. Avoid confusing it with a blocked live process.|Kill the zombie harder with SIGKILL.|How do you handle several children exiting together?|Correct reaping mechanism and multi-child race handling.
T|How should a service shut down on SIGTERM?|Route notification into normal control flow, stop accepting work, wake waiters, release owned resources and exit within policy.|Keep signal handlers within async-signal-safe operations or use an appropriate signal-wait/event mechanism. Calling arbitrary logging/allocation from a handler can deadlock.|Perform all cleanup with printf and mutexes inside the handler.|How does a self-pipe help?|Safe notification and orderly lifetime sequencing.
D|A service runs manually but fails at boot. What compare?|Compare environment, working directory, credentials, dependencies, device readiness and actual logs/exit code.|Use explicit paths and service dependencies. Boot can expose races with device creation or mounted persistence. Adding an arbitrary sleep hides rather than proves ordering.|Put sleep 30 before starting it.|What evidence identifies a missing runtime dependency?|Reproduce the actual service execution context.
T|What is virtual memory and why can RSS differ from address-space size?|Virtual addresses map process regions; resident set measures currently resident pages under the reported metric.|Mappings can be uncommitted, file-backed, shared or swapped. A single number cannot establish a leak; compare workload and page accounting over time.|Virtual size equals physical RAM exclusively owned by the process.|What would you observe during copy-on-write?|Separate mapping, residency, sharing and growth evidence.
D|A deleted log still occupies disk space. Why?|An open descriptor can keep the unlinked file's data alive until the last reference closes.|Inspect the owning process/descriptors, then use a controlled reopen/rotation strategy. Deleting names alone does not force a service to release open files.|Filesystem corruption is the only explanation.|How should log rotation coordinate with a long-running writer?|Name versus open-object lifetime and safe operational remedy.
''')

add('POSIX I/O, IPC and readiness','EL','M03','R20; R21; R22','Linux/POSIX; distinguish socket, pipe, regular-file and terminal semantics.',r'''
C|Implement write-all with partial progress and a deadline.|Keep an offset, advance only after positive writes, retry EINTR and wait for readiness after EAGAIN without resetting the total deadline.|For nonblocking output recompute remaining time from a monotonic deadline. Define zero-progress and peer-close handling. A timeout may occur after partial output, so report bytes sent.|Retry the whole original buffer after every short write.|Can the caller safely retry a partly sent command?|Correct accounting, bounded wait and explicit partial-completion contract.
T|What can a read result mean?|Positive means that many bytes, zero has object-specific end/no-data semantics, and negative requires checking errno.|For a pipe/socket stream, zero commonly means EOF after buffered data is consumed; terminal VMIN/VTIME modes need separate interpretation. Never cast a negative ssize_t to size_t first.|Zero always means wait and retry forever.|What changes with a datagram socket?|Object-specific return interpretation and no unsigned error conversion.
C|Design an absolute timeout for an I/O loop.|Compute one monotonic deadline and recalculate remaining time after interruption or partial progress.|Round remaining units carefully for poll and cap conversions. When deadline expires stop rather than repeatedly polling with zero. Test repeated EINTR and a peer that trickles one byte at a time.|Restart the full timeout after each byte.|What if a wall clock is adjusted?|End-to-end deadline preserved despite progress/interruption.
D|poll reports readable but read returns EAGAIN. Is that impossible?|No; readiness can change before the operation or another consumer may take the data. Keep nonblocking handling correct.|Inspect ownership and events, then return to bounded waiting. Treat readiness as a hint about current state, not a reservation of bytes.|poll guarantees the requested byte count is available.|What about POLLHUP with buffered data?|Correct event interpretation and no busy spin or data loss.
C|Implement a bounded line reader over a byte stream.|Accumulate into a fixed-capacity buffer, handle fragmented delimiters and define oversize-line discard/recovery.|Return complete lines independently of read boundaries. Specify embedded zero policy and EOF with partial line. Test delimiter split, exact limit and overlong input followed by a valid line.|Use one fgets/read call and assume a complete record.|How do you resynchronize after oversize input?|Bounded storage, record state and progress on malformed input.
C|Create a pipe-based parent/child exchange without descriptor leaks.|Create the pipe, fork, close unused ends in each process and handle partial I/O and child status.|A remaining write end can prevent reader EOF. Use close-on-exec when appropriate and ensure error paths close every inherited descriptor. Test child exec failure and early close.|EOF arrives when the intended writer exits regardless of other copies.|How would you add a shutdown deadline?|Correct descriptor graph and EOF/reaping behavior.
T|When use shared memory instead of a pipe/socket?|Use it for a justified copying/throughput need, with explicit synchronization and version/lifetime contracts.|Shared memory is only storage. Define ownership, publication, restart/recovery and how processes agree on layout; pointers from one address space are not generally portable shared references.|mmap automatically makes updates safe and atomic.|How does one process crashing affect the shared state?|Data transport versus synchronization/recovery distinction.
D|Your epoll edge-triggered receiver stalls despite unread data. Why?|It may have failed to drain nonblocking input until EAGAIN, leaving data without a new edge.|Inspect actual epoll mode and owner; drain correctly while bounding fairness across connections. Level-triggered behavior differs. Reproduce with several records arriving before one event.|Read exactly one message for each edge.|How would backpressure and fairness change the loop?|Mode-specific state reasoning and a reproducible burst fixture.
T|How do stream and datagram sockets affect protocol design?|Streams preserve byte order, not message boundaries; datagrams preserve message units but can be lost/truncated depending on protocol/API.|Framing and partial I/O belong in a stream design; maximum message size and loss/reordering belong in datagram handling. Neither choice removes versioning or trust checks.|TCP preserves each application write as a packet.|How do you detect a truncated datagram?|Correct transport guarantees and application responsibilities.
D|A writer dies with SIGPIPE when its reader closes. How handle it?|Choose an explicit signal/socket policy and handle the corresponding EPIPE error rather than assuming peer availability.|For sockets, supported per-call flags may suppress SIGPIPE; for pipes a process signal policy may be needed. Preserve partial-progress/error semantics and clean up connection state.|Retry writes forever until the reader returns.|What if another thread changes the process-wide signal disposition?|Peer-close behavior and scope of chosen mechanism.
''')

add('Threads, locks and shutdown','All','M04','R23; R26','POSIX userspace unless stated; kernel and RTOS primitives have different contracts.',r'''
C|Implement a mutex/condition-variable bounded queue.|Protect queue and stop predicates with one mutex; wait in while loops; modify predicates before notifying.|Producer waits while full and not stopped; consumer while empty and not stopped. Define drain/discard policy and broadcast on stop so blocked producers and consumers can exit.|Use if instead of while because one signal means one item.|What if two consumers wake for one item?|Predicate correctness, ownership and shutdown of both wait sets.
D|Why can a condition wait return with no usable item?|Wakeups can be spurious, or another thread may consume the item before this waiter regains the mutex.|The predicate is shared state, not the notification count. Recheck under the same mutex; an event-only mental model creates races.|A signaled condition variable permanently stores one item.|When is broadcast necessary?|Explain wake/reacquire/recheck interleaving.
C|Publish an immutable configuration snapshot between threads.|Use mutex-protected ownership or a correct atomic publication plus a safe reclamation scheme.|Release/acquire can publish initialized fields, but swapping a pointer does not keep the old snapshot alive for readers. A reference/lifetime strategy is still required.|An atomic pointer eliminates use-after-free.|How would you choose mutex versus RCU-like design?|Separate publication from reclamation and justify simplest correct design.
D|The queue deadlocks only during shutdown when full. What inspect?|A producer may wait forever after the consumer stops, or stop may not wake the full-queue wait set.|Draw stop, queue occupancy and each waiter. Set stop under the lock, broadcast relevant conditions, define whether to drain, then join before destroying synchronization objects.|Set a volatile stop flag and sleep before freeing the queue.|Which order should joins and queue destruction follow?|Concrete interleaving and lifetime-safe shutdown sequence.
T|What is priority inversion?|A high-priority task blocks on a resource held by a lower-priority task, which can be delayed by medium-priority work.|Priority inheritance can reduce that blocking but does not shorten long critical sections, prevent deadlock or fix interrupt masking. Actual mutex support/protocol must be verified.|Raise every task to the highest priority.|When does priority ceiling help?|Distinguish scheduling inversion from deadlock and resource contention.
D|Two individually correct mutex-protected functions deadlock together. Why?|Their composed lock acquisition order may form a cycle or callback reentry may acquire an already-held lock.|Write the lock graph and enforce a global order or reduce nesting. Use a minimal two-thread schedule to demonstrate the cycle; timeouts alone do not make the design correct.|Add another mutex around each function.|How do callbacks affect lock-order analysis?|Graph-based cause and a verified ordering change.
T|Why is volatile count++ unsafe across threads?|It is a read-modify-write without atomicity or a happens-before relation; conflicting unsynchronized access can be a C data race.|A mutex protects a compound invariant. An atomic counter can count independently but may not protect associated payload fields. Tooling can find some races, not prove absence.|Volatile forces memory access, therefore it synchronizes threads.|Would relaxed fetch_add publish a queue entry?|Separate access visibility, atomicity and ordering.
C|Design a single-producer/single-consumer ring publication protocol.|Assign one writer to each index; publish produced slots with release/acquire and protect slot reuse with the reverse ordering.|Specify index width/wrap and no third writer. A count field written by both sides can defeat the design. Start with a mutex implementation unless the lock-free requirement is justified.|Make head and tail volatile and rely on x86.|Which access proves the consumer finished reading a slot?|Both publication and reuse ordering plus restricted concurrency model.
D|A test passes under a debugger but races in release. What next?|Treat debugger timing as an interference change; reproduce with controlled stress and supported race instrumentation, then reason about shared accesses.|Do not fix by inserting sleeps. Preserve the original failing workload/configuration and test a schedule that exposes the missing synchronization.|Optimization is broken, so ship -O0.|Can a race tool miss the bug?|Reproducible evidence and a synchronization argument independent of timing.
T|When should a thread own a resource exclusively?|When single ownership simplifies state and avoids contended access, such as one UART writer or one logging task.|Other tasks send bounded messages to the owner; define queue overload and shutdown. Ownership avoids some locks but still requires synchronization at the handoff and lifecycle boundaries.|Single-owner design removes every concurrency issue.|What if the owner stalls?|Bounded handoff, overload/failure behavior and measurable tradeoffs.
''')

add('Architecture, MMIO, interrupts and DMA','KD/FW','M05','R24; R13','Architecture and cache/controller details must be checked against actual target manuals.',r'''
T|How do MMU and MPU differ?|An MMU translates virtual addresses with protection; an MPU generally enforces protection over configured regions without full virtual translation.|Capabilities vary by core. Linux application processors and Cortex-M firmware have different memory models and boot responsibilities; do not infer features from the ARM name alone.|Every ARM target runs the same virtual-memory Linux.|How does an MPU help isolate firmware tasks?|Target-specific capability and OS consequence.
T|What is MMIO and why not use an ordinary pointer casually?|Device registers are accessed through mapped addresses with device-specific width, side-effect and ordering rules.|In Linux use mapped I/O and accessors; MCU code follows vendor/compiler register definitions. A read can clear a flag and a write can acknowledge it, so normal variable assumptions fail.|Volatile makes every register sequence correct.|What about posted writes or required readback?|Side effects, access width and ordering qualifications.
D|A register read always returns zero. How investigate?|Verify address mapping, clock/reset/power, access width, permissions and pin/peripheral configuration before assuming the register value is meaningful.|Compare target reference manual and a known identity/status register. A disabled clock or wrong physical-to-virtual assumption can imitate broken hardware. Record fault/status evidence.|Write random values to neighboring registers.|How would you distinguish bus fault from legitimate zero?|Ordered, non-destructive checks tied to target documentation.
T|Why can DMA fail despite correct CPU memory contents?|Device addressing, mapping, ownership, cache maintenance, alignment or ordering may be wrong.|A CPU virtual pointer is not a DMA address. Use the DMA API, check mapping errors/direction and transfer ownership correctly. Coherent allocation still needs ordering of descriptors/status.|Cast the pointer to an integer and program the device.|What changes with an IOMMU?|Address-domain and ownership distinctions.
D|A DMA buffer works on one board but contains stale data on another. Why?|A coherence/ownership assumption may differ; inspect mapping direction, sync transitions and cache-line sharing.|Use the selected platform's DMA APIs rather than ad hoc cache flushing. A small adjacent CPU field sharing a cache line can complicate streaming-buffer ownership.|Disable all caches permanently.|How would you test CPU/device simultaneous access misuse?|Concrete ownership timeline and portable API correction.
T|What is interrupt latency versus handler execution time?|Latency is delay from the relevant event to service; handler time is work after entry, and end-to-end response includes later scheduling/queueing.|Define measurement timestamps and instrument the physical event if claiming external latency. A userspace log alone may omit controller/firmware delays.|Measure printf duration in the ISR.|How does deferred processing change the response budget?|Explicit timeline and observer-effect awareness.
T|How do barriers differ from locks?|Barriers constrain ordering; locks also implement a mutual-exclusion/ownership protocol under their contract.|A barrier does not stop two CPUs updating the same compound state. Compiler, CPU and device ordering are distinct concerns. Use high-level primitives appropriate to the selected memory model.|A memory barrier makes increment atomic.|When can release/acquire replace a full barrier?|Match guarantee to actual shared-state protocol.
D|An IRQ fires continuously after enabling a peripheral. What inspect?|Check source status, trigger/polarity, acknowledgement semantics and whether the underlying level condition has been cleared.|Do not indiscriminately mask every IRQ or use an unrelated clear sequence. Record status before/after the documented acknowledgement; shared IRQ handlers must identify ownership.|The interrupt controller is always faulty.|How do edge and level triggers change recovery?|Target-specific cause acknowledgement and safe diagnostic sequence.
C|Implement rollover-safe elapsed-time comparison for a timer.|Use unsigned modular subtraction under a documented maximum-interval bound and compare elapsed with the timeout.|For a fixed-width counter, require observations/intervals within the intended wrap model; common ordering schemes restrict intervals to less than half the range. Never transplant formulas across unknown widths.|Compare now>=start+timeout without considering overflow.|What if the device sleeps through multiple wraps?|State arithmetic width, bound and missed-wrap limitation.
T|Why is disabling local interrupts not a multicore lock?|It prevents selected local interrupt interleavings, not another CPU from accessing the same object.|Also consider nonmaskable exceptions, preemption and target-specific RT semantics. Choose a lock/context design for every actual concurrent actor rather than relying on one CPU's state.|No interrupt means no concurrency anywhere.|How would an ISR and task share state on a uniprocessor MCU?|Enumerate actors and primitive scope.
''')

add('Cross-build and boot diagnosis','EL/KD','M05/M06','R02; R03; R18','Buildroot 2026.08.1 planned virt lane; no executed guest in this release.',r'''
T|What is a cross toolchain and sysroot?|The toolchain emits code for another target; the sysroot supplies target headers/libraries and related link context.|Compiler target, ABI, libc and loader must agree with the image. Host headers/libraries accidentally found during a build can create a plausible but wrong binary.|A sysroot simulates the target CPU.|How would you prove which libraries were linked?|Toolchain/ABI/loader consistency with inspected artifacts.
D|An AArch64 binary exists but cannot execute. What check?|Inspect ELF machine, interpreter, ABI and target libraries, plus execute permissions and mount policy.|Exec-format error differs from a missing dynamic loader, which can produce a missing-file symptom. Use file/readelf and actual target logs rather than recompiling blindly.|Copy the host libc onto the target.|How do static linking and QEMU user mode affect diagnosis?|Differentiate architecture, interpreter and permissions failures.
C|Write a cross-build configuration that avoids host leakage.|Select the target compiler, sysroot and find-root policy explicitly; use target pkg-config metadata or a controlled wrapper.|Record the actual toolchain file, link line and ELF interpreter. A successful compile is not execution proof. Test one intentionally missing target dependency.|Add host /usr/include until headers resolve.|Which CMake searches should run on the host?|Correct separation of build tools and target artifacts.
T|How do QEMU user mode and system mode differ?|User mode translates target application execution against a host syscall environment; system mode emulates a machine with a guest kernel.|Use system mode for driver/kernel/boot learning. Neither mode automatically verifies physical timing, wiring, DMA controller behavior or real peripheral quirks.|Running a target ELF in user mode tests its kernel module.|When can user mode still be useful?|Scope and limitations tied to the intended test.
D|Remote debugging shows wrong source lines. What inspect?|Check binary/debug-symbol build identity, load addresses, source paths, optimization and architecture settings.|Use symbols from the exact deployed image. Source checkout resemblance is insufficient. Break at a known function and verify disassembly before trusting variables optimized away.|The debugger is unreliable; ignore its output.|How do separate debug files or ASLR affect setup?|Matching artifact identity and address/source mapping.
T|Explain a platform boot chain without assuming U-Boot everywhere.|Identify actual ROM/firmware stages, optional bootloader, kernel handoff, rootfs and init for the selected platform.|A QEMU direct-kernel boot can bypass a bootloader; MCU reset/vector startup is a different chain. Verify each board's trusted/loaded image and handoff data.|Every Linux system boots through U-Boot.|Where does device tree enter the chain?|Platform-specific sequence and diagnostic boundaries.
D|Kernel boots but cannot mount root filesystem. What check?|Check root device naming, driver built-in availability, filesystem support, image attachment and command line.|A driver built only as a module may not exist before root is mounted unless an initramfs provides it. Separate storage discovery from filesystem integrity.|Rebuild userspace application first.|How would an initramfs help identify the failure?|Stage-localized diagnosis and required early drivers.
D|Kernel finds rootfs but reports no working init. What next?|Inspect init path, executable format, loader/libraries, permissions and the configured init argument.|An existing /sbin/init can fail because its interpreter is missing. Compare the rootfs contents and kernel log return codes; do not treat all boot failures as root-device errors.|Any shell script named init always works.|Which device mounts are needed for a minimal init environment?|Distinguish mounting root from executing userspace.
T|What is an initramfs compared with persistent rootfs?|An initramfs is an early RAM-backed filesystem populated from an archive; it can perform discovery and handoff before another root.|It is not necessarily a compressed disk partition, and changes vanish unless explicitly persisted. Define switch/root handoff and tool availability for the chosen setup.|initramfs writes automatically survive reboot.|Why might it contain storage or decryption tools?|Early userspace role and persistence boundary.
T|What belongs in a BSP?|Board/platform enablement such as boot configuration, kernel/device-tree settings, drivers and integration metadata for the chosen hardware.|The exact scope varies by vendor. Treat board revision, pinmux, regulators, clocks and maintenance patches as traceable inputs, not a generic tarball that works on every board.|A BSP is only a cross compiler.|What would you upstream versus keep product-specific?|Hardware enablement and lifecycle/maintenance understanding.
''')

add('Kernel contexts, allocation and concurrency','KD','M07','R26; R27; R28; R30','Linux 6.18 concepts; verify selected configuration, especially PREEMPT_RT.',r'''
T|What determines whether kernel code may sleep?|The current execution context and held primitives determine whether sleeping is allowed, not merely the function's name.|Hard-IRQ and atomic sections cannot perform operations that may block. Task context can also become non-sleepable while holding relevant locks or disabling preemption/interrupts.|All kernel code can sleep because it runs privileged.|What about a threaded IRQ handler?|Classify caller/context and each potentially sleeping operation.
D|A warning says sleeping function called from invalid context. What inspect?|Trace the call path, held locks, IRQ/preemption state and a potentially sleeping operation such as allocation or user access.|Fix the context/ownership design; GFP_ATOMIC is not a universal patch for an operation that fundamentally needs sleep. Move appropriate work to a worker when justified.|Replace every allocation flag with GFP_ATOMIC.|How would you prove cleanup remains safe after deferral?|Context analysis plus a lifetime-safe redesign.
T|How choose mutex, spinlock_t or raw_spinlock_t?|Choose by context, scope and configuration; mutexes sleep, while raw spinlocks remain strict spinning primitives.|PREEMPT_RT changes spinlock_t semantics, so “spinlocks always disable interrupts/preemption” is not a universal claim. Keep raw critical sections tiny and never perform sleepable bus access there.|Use spinlocks for every kernel object because they are faster.|Which primitive fits a hard-IRQ-shared small state?|Version/configuration qualification and legal lock nesting.
T|How do kmalloc and vmalloc differ?|kmalloc gives kernel memory with relevant physical-contiguity properties; vmalloc maps virtually contiguous space that need not be physically contiguous.|Neither API alone establishes DMA suitability or device addressability. Allocation size, context and failure handling matter; use the DMA API for device buffers.|vmalloc memory is always usable directly for DMA.|What about high-order allocation failures?|Address/layout distinction and appropriate allocation context.
D|A probe leaks resources on its third failure path. How fix?|List acquisitions and dependencies, then unwind or use suitable managed resources while explicitly quiescing asynchronous activity.|Inject failure after each acquisition and verify no IRQ/work/timer can access released state. devm does not itself define the logical stop sequence.|devm removes every cleanup requirement.|How do shared references survive unbind?|Complete resource dependency/lifetime analysis.
T|What does a wait queue provide?|It coordinates sleeping waiters with a condition becoming true; the state predicate and synchronization remain the driver's responsibility.|Register/check/wake ordering must prevent lost wakeups. Recheck after wake and handle signal interruption; notification is not the data itself.|One wake_up stores one event permanently.|Why is wake_up alone insufficient?|Predicate, visibility and interruption reasoning.
T|When use a workqueue?|For appropriate asynchronous process-context work that may need to sleep, with explicit scheduling and teardown rules.|Coalesce repeated work carefully; it may represent state needing service rather than one queued execution per event. Cancel/flush correctly and prevent requeue before freeing state.|Queueing work guarantees one callback per hardware event.|How would unbind race with a self-requeueing worker?|Deferred-work ownership and quiescence order.
T|What problem does RCU solve?|It allows appropriate readers to observe published versions while reclamation waits until pre-existing readers are done.|Writers still need update coordination and correct publication; grace periods address lifetime, not every data race. Rules depend on RCU flavor/context.|RCU means writers need no locks and can free immediately.|Why is synchronize_rcu not just a delay?|Publication versus reclamation and relevant reader scope.
D|A timer callback accesses freed driver state after removal. What happened?|Teardown freed state before preventing new activity and synchronizing outstanding callbacks/work.|Disable the event source/rearming path, use the appropriate synchronous cancellation and avoid lock inversion with the callback. Mere removal from a registry does not stop execution already in flight.|Set the pointer to NULL after free.|What if the timer queues work that rearms the timer?|Full asynchronous dependency graph and ordered quiescence.
T|Why are atomics insufficient for many kernel invariants?|An atomic operation protects a particular operation, not an arbitrary relationship among payload, count, lifetime and readiness.|Use appropriate ordering and ownership or a lock that covers the invariant. A refcount also has a different purpose from an arbitrary integer counter.|Making every field atomic makes the structure race-free and correct.|How do reference counts interact with object publication?|Compound-state and lifetime reasoning beyond atomicity.
''')

add('Driver interfaces and lifetimes','KD','M08','R29; R30','Linux 6.18.7 intended build; no driver code executed in this release.',r'''
T|Why use copy_to_user/copy_from_user?|User pointers need controlled access with fault/error handling; directly dereferencing them violates kernel interface rules.|Check the exact helper return contract: common copy helpers return bytes not copied, not a conventional negative errno. User access can fault/sleep in applicable contexts.|Treat copy_to_user returning nonzero as a positive byte count successfully copied.|How do partial copies affect read semantics?|Correct access/context/return handling.
D|A read succeeds but poll never wakes. What inspect?|Compare the readiness predicate, poll wait registration, state update visibility and wake path.|read and poll must describe the same protected queue state. Test empty-to-nonempty with a waiter already registered and with an event racing registration.|poll can just return readable unconditionally.|How do hangup/error states appear?|Consistent predicate and lost-wakeup prevention.
T|What should a character read return when no data exists?|It depends on blocking policy: wait interruptibly, return EAGAIN for nonblocking, or EOF only for a genuine end condition.|Zero is not a generic “try later” marker for a live stream. Define zero-length request, signal interruption and partial-progress behavior in the ABI.|Return zero whenever queue is empty.|How does this affect a userspace cat loop?|Object-specific EOF and blocking semantics.
D|A module unloads while an open descriptor still calls it. What review?|Review file-operation/module ownership, open references and separate device-object lifetime during unbind.|Module code lifetime and device state lifetime are related but different. A driver can remain loaded while a detached device must reject operations safely.|A global boolean removed prevents all lifetime bugs.|How would you keep per-open state alive?|Distinguish code reference, object reference and active operation lifetime.
T|How do you design a stable ioctl ABI?|Use a justified operation, fixed-width fields, explicit layout/version/reserved handling and compatibility rules; validate sizes and values.|Avoid native pointers/long in shared structures unless a documented compat strategy exists. Prefer established subsystem interfaces when they fit. Unknown commands must fail predictably.|Expose the driver's internal struct directly.|How would 32-bit userspace on 64-bit kernel work?|Layout/compat/error policy and a justified need for ioctl.
C|Design a poll-capable bounded kernel queue.|Protect queue state, register poll waiters with the supported API, report readiness from the same predicate as read/write and wake after changes.|Use sleepable user-copy paths without raw spinlock held; stage data or choose an appropriate lock design. Multi-client consumption needs explicit ownership and partial-fault semantics.|Hold a spinlock while copying arbitrary userspace buffers.|How do you preserve data on a failed copy?|Readiness, copy context and concurrent-consumer contract.
T|What do managed resources simplify and leave unsolved?|They release registered resources at device lifecycle boundaries, reducing manual error unwinding.|The driver must still stop IRQ/work/timer activity and manage references outside that lifetime. Resource registration order affects release dependencies.|devm guarantees no use-after-free on unbind.|When would devm be inappropriate for a longer-lived object?|Logical stop sequence beyond automatic release.
D|A driver reports success after hardware initialization fails. What consequence?|Userspace sees a bound but unusable device and later faults become misleading; propagate the real failure and unwind state.|Differentiate optional feature failures from required initialization. Log context without masking an error code or spamming retries. Test failure at each setup boundary.|Probe should always return zero so the system boots.|How do you handle a temporarily unavailable provider?|Required/optional/deferred failure semantics.
T|Why is a learning char device not always a production sensor interface?|Subsystem APIs provide established units, discovery, buffering and userspace conventions that a private interface would duplicate.|Use IIO/hwmon/input/tty/etc. based on device semantics. The char queue teaches copying/waits/lifetimes; it does not justify a custom ABI for every peripheral.|A custom ioctl is always simpler and therefore better.|What behavior would IIO supply for an accelerometer?|Subsystem-fit tradeoff and educational scope.
D|A multi-client driver duplicates or loses records. Where look?|Clarify record ownership and lock coverage across readiness check, user copy and consume; two readers may observe the same head.|Define whether reads consume globally or each open has a cursor. Handle partial faults without silently discarding unreported data. A lock around count alone may be insufficient.|Increase buffer capacity until the race disappears.|How would you test two readers deterministically?|Explicit consumer semantics and race-free commit point.
''')

add('Device tree, GPIO and platform integration','KD','M09','R13; R29; R31','Linux 6.18 interfaces; physical board image/pinmux still pending.',r'''
T|What does device tree describe?|It describes hardware topology/resources and compatible bindings for software to interpret, not an arbitrary driver-instantiation script.|Bindings are an ABI beyond one kernel driver. Clocks, interrupts and pinctrl resources must reflect hardware. Node names alone should not be used as a general stable matching interface.|Add any property needed to store the driver's private runtime state.|Why should a binding cover hardware not yet used by the driver?|Hardware description versus implementation policy.
D|A device-tree node exists but probe never runs. What inspect?|Check the live tree, status, compatible match, driver build/module availability and bus/device creation path.|Inspect actual booted DTB rather than source alone. Overlay application or wrong deployment can make a correct source irrelevant. Differentiate missing match from probe returning an error.|Rename the node to the driver function name.|What if the compatible is correct but provider is deferred?|Systematic enumeration/matching/probe boundary checks.
T|When should probe return deferred-probe error?|When a required resource provider is expected but not ready under the relevant API contract.|Propagate the actual provider error rather than converting every failure to ENODEV. A malformed property or absent hardware is different from a deferred dependency.|Always retry every probe error forever.|How do logs help avoid deferred-probe spam?|Correct transient versus permanent failure classification.
C|Outline a GPIO IRQ platform driver using modern resources.|Match a binding, acquire a GPIO descriptor, derive/request IRQ as appropriate, keep hard handler minimal and expose the event through a fitting interface.|Use the selected tree's exact APIs and a threaded path if operations sleep. Document polarity/debounce and prevent work/IRQ after teardown. No arbitrary numeric GPIO assumption.|Hardcode a global GPIO number from another board.|How do you prove physical pin routing?|Descriptor/context/lifetime design plus board-doc verification.
T|How do GPIO logical values differ from electrical levels?|Descriptor polarity can map logical active/inactive to physical high/low; open-drain and controller capabilities further matter.|Use binding/controller semantics consistently. A logical one on an active-low line may drive low. Verify with a meter/analyzer and the exact circuit.|Logical one always means 3.3 V.|What if a GPIO provider is on an I2C expander?|Polarity and sleepable-access qualification.
D|A GPIO driver works on a simulator but not the board. Why?|Pinmux, power, pull resistors, polarity, voltage, board routing or actual IRQ/controller behavior may differ.|Use board schematic and SoC pin control documentation; identify shared functions before writing. Simulation validates only modeled semantics, not electrical configuration.|QEMU passing proves the pin and interrupt timing.|What measurement separates routing from driver logic?|Separate modeled state from real physical verification.
T|How do clocks and regulators affect probe and runtime?|They provide required timing/power resources; enabling/configuring them and releasing references must follow device dependencies.|Check sequencing, rates and failure paths. Runtime PM can power down a device between uses, so register access requires the appropriate active state.|A mapped register is usable regardless of clock/power.|What must happen during suspend/resume?|Resource dependencies and balanced ownership.
D|An overlay compiles but the wrong device appears. What inspect?|Inspect the applied live tree, target phandles, bus location, address cells and selected base DTB.|Compile success is syntax-level evidence, not correct hardware binding. Verify overlay deployment and conflicts with existing nodes/drivers; validate schemas when supported.|If dtc accepts it, the hardware description is correct.|How would you detect duplicate address use?|Syntax versus semantic/live-deployment checks.
T|Why validate a device-tree binding schema?|It checks declared structure/constraints and catches many property and example mismatches before runtime.|It does not prove wiring, pinmux safety or actual device behavior. Keep examples consistent and avoid breaking the established ABI for convenience.|Schema validation replaces hardware tests.|What should happen to unknown vendor properties?|Constraint/ABI reasoning and validation limits.
D|A button produces many interrupts for one press. How respond?|Confirm bounce/electrical behavior and trigger configuration, then use an appropriate hardware/software debounce policy.|Measure bursts, define acceptable response/latency and avoid sleeping in a hard handler. Prefer an existing input/GPIO subsystem driver if it already fits.|Busy-wait in the hard IRQ for 100 ms.|What if legitimate fast edges must be retained?|Signal semantics, measured debounce and context-correct implementation.
''')

add('Buses, IIO, DMA and power','KD','M13','R14; R15; R24','Sensor register/board assumptions must follow actual datasheet and selected kernel source.',r'''
T|Compare I2C, SPI and UART integration concerns.|I2C has addressed shared-bus transactions, SPI controller/chip-select/mode transactions, and UART an asynchronous byte stream needing explicit framing.|Electrical levels, clocks, chip selects, pull-ups and error observability differ. A peripheral interface name alone does not specify application protocol, voltage or Linux subsystem API.|All three buses automatically deliver application packets.|Which conditions are visible only with a logic analyzer?|Transaction and physical/protocol distinctions.
D|An I2C register read returns NACK. What investigate?|Check power/voltage, address convention, wiring/pull-ups, controller configuration and the documented transaction sequence.|Separate a 7-bit address from an 8-bit address byte. Confirm repeated-start and register pointer behavior against the actual device. Do not scan/write arbitrary buses indiscriminately.|Shift every failing address until it works.|How do you distinguish absent hardware from transient bus error?|Datasheet-based, bounded, non-destructive investigation.
T|What must match for an SPI peripheral?|Controller chip-select routing, clock polarity/phase, frequency, word size and device-specific command framing.|A correct mode still leaves byte order, dummy cycles and transfer continuity. Validate against datasheet/logic trace, not only successful ioctl return.|SPI has addressing exactly like I2C.|What happens if chip select toggles between command and response?|Complete transaction contract.
C|Convert ADXL345 register bytes to physical units.|Decode according to configured range/resolution and register format, then apply the documented scale and units exposed by IIO.|Do not assume a generic int16_t always represents the full device format. Test negative/raw fixtures and check orientation sanity with the actual configured scale; no measurement is supplied here.|Raw count is already acceleration in m/s².|What does the IIO scale represent?|Configuration-aware numeric/unit conversion and independent fixtures.
T|Why expose sensor channels through IIO?|It supplies established channel/raw/scale/buffer conventions and userspace discoverability for appropriate sensors.|Reuse or extend an existing supported driver rather than deploy a duplicate casually. A teaching variant belongs in an isolated tree and must explain its scope.|Every sensor requires a private /dev node and ioctl.|When would hwmon be a better fit?|Subsystem semantics and production maintenance tradeoff.
D|Sensor samples are plausible but scaled incorrectly. What inspect?|Compare configured range/resolution, sign extension, byte order, scale units and client conversion path.|Use a known register fixture before physical orientation tests. Plausible numbers are weak validation; record actual configuration and the expected physical relation.|Calibrate until the graph looks smooth.|How would you separate offset error from scale error?|Independent numeric oracle and configuration traceability.
T|What is a triggered IIO buffer?|It captures defined channel scans associated with a trigger, with specified layout/timestamp semantics.|Scan masks, alignment and timestamp units must match userspace decoding. Buffer mode and direct register access can need exclusion/serialization; follow the selected IIO API.|Read a C struct from the buffer using host padding.|How do you validate scan layout?|Explicit binary layout and mode/lifetime handling.
D|A bus read sleeps inside a hard IRQ and warns. What change?|Move appropriate bus work to a threaded/deferred sleepable context and keep the hard path within its legal operations.|Preserve source acknowledgement, event coalescing, ownership and teardown. Simply substituting an atomic allocation does not make I2C transfer sleep-free.|Use GFP_ATOMIC around the bus read.|How do you avoid losing level-triggered events during deferral?|Context-correct transfer and interrupt/lifetime analysis.
T|What is runtime PM versus system suspend?|Runtime PM manages individual devices during normal operation; system suspend coordinates a broader system power transition.|Balance active references and error paths; avoid accessing powered-down registers. A pending worker and its lifetime must be reconciled with suspend/removal.|Runtime PM is just calling sleep in idle code.|How do you test failure during resume?|State/refcount balance and recovery semantics.
D|DMA completion occurs after the client buffer was released. What failed?|The transfer's ownership/lifetime outlasted the caller's storage; cancellation/completion synchronization was incomplete.|Define who owns buffers until completion and how shutdown prevents new submissions, cancels/drains transfers and returns ownership. A completion flag alone does not pin memory.|Free immediately after submitting because DMA is asynchronous.|How does mapping/unmapping fit the lifetime?|Complete submit→device→completion→release ownership timeline.
''')

add('MCU startup, peripheral state and faults','FW','M11','R12; R18','STM32F446RE planned hardware; exact registers/startup require its reference manual and build.',r'''
T|What happens before main on a Cortex-M firmware target?|Reset uses the vector table/startup path, establishes initial execution state and initializes the C runtime's required memory before main.|Typical startup copies .data and zeroes .bss, with clock/FPU/cache setup according to the target. Bootloader relocation changes vector/address assumptions; inspect actual startup and linker files.|main is always the first instruction executed.|Where do initial stack pointer and reset vector come from?|Trace actual reset-to-main dependencies.
C|Write the logic for nonblocking UART receive processing.|Use a bounded ISR/DMA-to-task handoff and a stateful parser; the task processes available bytes and timeouts without waiting forever.|One actor owns each buffer/index or a documented synchronization primitive protects it. Define overflow, partial frame and error reset. Actual UART register/DMA configuration is target-specific.|Read until a full packet inside the ISR with no bound.|How do overrun/framing flags affect parser recovery?|Bounded ISR work and explicit ownership/recovery.
D|Firmware enters a fault handler after an interrupt. What capture?|Preserve stacked PC/LR/registers, relevant fault status and stack/context information before destructive logging/reset.|Decode addresses using the exact ELF/map and fault registers for the core. A corrupt stack can make the frame unreliable. Avoid complex allocation or unsafe peripheral calls in the handler.|Always assume the last source line caused the fault.|How do you persist a small crash record across reset?|Artifact identity, minimal safe capture and competing hypotheses.
T|What are .text, .data, .bss and stack?|They represent code/constant placement, initialized writable data, zero-initialized storage and call/task execution storage under the selected toolchain.|Linker placement and startup establish runtime addresses; RTOS tasks usually need separate stacks. A map file can reveal RAM pressure but not all dynamic peak usage.|.bss occupies identical bytes in the load image and runtime RAM.|How would you budget multiple task stacks?|Load/run memory distinction and measured stack margin.
T|How should a watchdog be fed?|Only after required system components demonstrate progress within policy, using the correct watchdog timing/window contract.|A periodic ISR feeding unconditionally can hide a deadlocked application. Test stopped workers, reset reason and boot recovery. Independent watchdog clock behavior is target-specific.|Feed as fast as possible from any loop.|What if one task is alive but its data is stale?|Health/progress criteria and actual stall-injection test.
D|Timer periods drift when other work increases. Why?|Relative scheduling, blocked execution, interrupt latency or incorrect clock assumptions may affect the observed period.|Use a hardware/monotonic reference, schedule against intended deadlines where appropriate and measure jitter. A nominal timer reload is not end-to-end periodic behavior.|Increase optimization until drift disappears.|How do missed periods change the state machine?|Clock/scheduling distinction and measured timeline.
T|What must peripheral initialization establish?|Clock/reset/pinmux, transfer format, buffers/interrupts and status-clearing sequence according to the specific peripheral contract.|Enable interrupts only after state and handlers are ready; clear stale conditions safely. Reverse dependencies during shutdown. Register-write order may matter.|Copy register values from a different MCU family.|How do you verify actual peripheral clock?|Manual-based sequence and observable verification.
C|Design a debounced button state machine.|Sample or timestamp edges, require a defined stable interval and emit one logical transition under an explicit policy.|Keep raw electrical edges separate from stable application state; handle timer wrap and repeated edges. Choose interval from measured behavior/requirements, not a universal magic number.|Sleep inside the ISR until bounce ends.|How do you preserve fast legitimate events?|Defined timing semantics, bounded ISR and transition tests.
T|When use polling, interrupt or DMA?|Choose by data rate, deadline, CPU budget, complexity and peripheral support.|Polling can be simplest for bounded short checks; interrupts avoid constant polling; DMA reduces per-byte CPU work but adds buffer/cache/lifetime complexity. Measure rather than assuming DMA always wins.|DMA makes transfers free of CPU and correctness costs.|What happens for tiny infrequent transfers?|Workload-based tradeoff and ownership overhead.
D|MCU application works after debugger download but not power-cycle. Why?|Debugger initialization, reset type, vector/link address, boot mode, startup memory or timing dependencies may differ.|Test a real cold boot and inspect boot pins/options, reset reason and startup trace. A debugger can mask uninitialized RAM or clock setup defects.|The board is defective because debug run succeeds.|How would bootloader offset change startup?|Cold-boot versus debug-state distinction and reproducible checks.
''')

add('RTOS timing, priorities and fault policy','FW','M12','R10; R32','Zephyr v4.2.0 planned; RTOS scheduling/ISR API rules are implementation-specific.',r'''
T|How assign task priorities?|Start from deadlines and blocking/resource dependencies, then verify schedulability and measured interference on the selected RTOS.|High frequency alone is insufficient if critical work blocks behind long shared-resource ownership. Keep noncritical logging/inference from controlling essential deadlines.|Give all tasks equal highest priority.|What assumptions permit rate-monotonic analysis?|Deadline/resource reasoning and explicit scheduler assumptions.
D|A high-priority task starves lower-priority maintenance. What inspect?|Check whether it ever blocks/yields appropriately, workload exceeds capacity or priorities conflict with system progress requirements.|Measure execution and queueing; a watchdog may reset a system whose critical loop appears alive. Define bounded work per activation and overload behavior.|Raise the maintenance task until both are highest.|When is starvation intentionally acceptable?|Progress requirements and capacity-based remediation.
T|What can priority inheritance fix and not fix?|It can reduce priority inversion caused by a lower-priority mutex owner, but not deadlock, excessive work or every interrupt-disabled delay.|Check actual mutex implementation and nested-lock behavior. A queue/semaphore may not provide the ownership needed for inheritance.|Priority inheritance guarantees all deadlines.|How would you reduce blocking before changing priorities?|Bounded critical sections and accurate mechanism limits.
C|Design a watchdog supervisor with task progress counters.|Each required task advances a progress marker after meaningful work; supervisor feeds only if all required markers and freshness checks meet policy.|Guard counters/state consistently and account for legitimately idle tasks. A marker increment alone can miss stale sensor output; use a domain-relevant success predicate.|Every task feeds the hardware watchdog independently.|How do you test one stuck task without stopping the scheduler?|System-wide progress condition and deterministic stall test.
T|How do queues, mutexes and semaphores differ?|Queues transfer bounded data/ownership, mutexes protect owned critical sections, and semaphores represent counts/signals under their API rules.|Choose from invariant and context, not naming. ISR-safe variants and blocking restrictions are RTOS-specific; a counting semaphore alone does not carry packet identity.|They are interchangeable ways to delay a task.|Which primitive supports priority inheritance here?|Correct semantics and selected RTOS qualification.
D|A task stack overflows only during error logging. How investigate?|Capture stack usage/watermarks and call depth under worst relevant paths, including formatting and interrupt stacking rules.|Static stack estimates and observed high-water marks complement each other; neither guarantees all paths. Avoid recursion/large locals when unjustified and add defensible margin.|Double every stack forever without identifying usage.|Can a watermark miss an unexercised path?|Peak-path analysis and measurement limits.
T|What is a deadline miss and how should firmware react?|It is completion after the required time bound; reaction follows a specified fault/overload policy rather than silently accumulating stale work.|Choose skip/catch-up/degrade/fault based on control semantics. Count/report misses and preserve a safe output rule; a good average period can hide misses.|Average frequency proves no deadlines are missed.|How would you distinguish release jitter from execution overrun?|Explicit timing contract and measurable response.
D|An ISR calls an RTOS queue API and crashes. What check?|Verify ISR-safe API/timeout restrictions, interrupt priority constraints, kernel state and buffer lifetime for this RTOS/port.|Some kernel services cannot be used from arbitrary interrupt priorities. Read the actual port documentation; do not assume FreeRTOS/Zephyr rules are identical.|Any API is safe if the ISR is short.|How does zero timeout differ from permission to call?|Selected API/port/context constraints.
T|What does native_sim validate and leave unverified?|It can test modeled RTOS application state and logic as a host program; it does not reproduce the chosen MCU's physical peripherals/timing.|Keep simulation, MCU build and actual board runs separate. Hardware startup, DMA coherency, IRQ priorities, clock accuracy and electrical behavior need their own evidence.|Passing native_sim proves the STM32 watchdog and deadlines.|Why choose its 64-bit qualifier explicitly?|Model scope and version/ABI awareness.
D|A task is running but the system produces no useful output. How diagnose?|Observe domain-level progress, queue age, resource waits and state transitions rather than just task heartbeat.|A livelock can keep counters moving while work never completes. Inject stale inputs/full queues to distinguish healthy idleness, blocking and useless retries.|Scheduler activity means the system is healthy.|What health metric would expose stale-but-active behavior?|Useful progress, not mere execution, as the health contract.
''')

add('Linux–MCU framing and recovery','EL/FW','M12','B01; R20; R21; R22','B01 frame is exact-message only; B03/I05 stream/session layers remain pending.',r'''
T|What does a reliable serial protocol need beyond a CRC?|Bounded framing, version/schema, sequence/session identity, deadlines, retries/duplicate policy and observable recovery.|UART supplies bytes, not application transactions. CRC detects accidental corruption, not malicious modification. A reset should establish a new session epoch so old commands are not accepted casually.|CRC guarantees delivery, order and authenticity.|How do you distinguish lost command from lost ACK?|Separate integrity, delivery, compatibility and session semantics.
C|Design duplicate-safe command handling.|Use session/sequence identifiers and cache a defined result or use idempotent commands; specify duplicate/retry retention bounds.|If an ACK is lost, repeating a toggle can undo the intended action. A set-target command is often easier to make idempotent. Persistent side effects need a durable transaction policy.|Retry every timed-out command without considering its effects.|What happens after a receiver reset loses its cache?|Explicit duplicate and reset semantics.
C|Implement bounded resynchronization after malformed input.|Consume input under a state machine, scan for a valid bounded header and reject bad size/version/checksum without unlimited growth.|Handle a candidate magic prefix at the end of a buffer; do not repeatedly retry the same bytes. Set a per-frame deadline and a bounded scan/work budget.|Allocate the declared length and wait indefinitely.|How do you test noise followed by a valid frame?|Memory/work/progress bound and deterministic noise fixtures.
C|Design version negotiation for a Linux–MCU link.|Exchange protocol version/capabilities and session identity before commands; accept only explicitly compatible schemas.|Distinguish transport frame version from message payload version if needed. Unknown optional fields may be skipped only under a documented length/schema policy. Reject unsafe unsupported commands.|Same compiler version means firmware protocols are compatible.|How do you upgrade one endpoint first?|Compatibility matrix and fail-safe unsupported behavior.
D|The same valid command executes twice after timeout. What failed?|The sender could not distinguish lost response from lost execution, and receiver duplicate handling was absent or insufficient.|Capture sequence/session and action/ACK timestamps. Fix transaction semantics rather than merely lengthening the timeout. Test ACK loss after action completion.|Use a larger CRC.|Would TCP alone make the command exactly-once?|Correct distributed side-effect reasoning.
T|How choose a protocol timeout?|Derive it from allowed response budget, transport duration, processing/queueing and recovery policy, then validate under load.|At a configured baud, framing bits determine byte time; scheduling and buffering add delay. State assumptions and retain end-to-end absolute deadlines. No universal timeout fits every board.|Pick one second because it is common.|How do retries affect worst-case command age?|Budget-based timeout with stale-command policy.
D|Communication stops after either endpoint resets. What investigate?|Check session/sequence state, handshake, buffer reset, UART reinitialization and peer detection; old state may be mistaken for valid continuation.|Inject reset at each protocol state and require bounded return to a compatible session. Keep reset epoch observable; avoid carrying stale command authority across reconnect.|Only reset both devices together.|How do you stop an old queued command after reconnect?|Session-scoped authority and bounded recovery tests.
C|Validate a packet field used as an array index.|Check field range against table length before access, then validate semantic support for that entry.|A CRC-valid packet can still contain invalid values. Bounds are necessary but a reserved command ID can still be forbidden. Reject before mutation/side effects.|A valid checksum proves every field is safe.|What if index arithmetic adds an offset?|Syntactic and semantic validation before action.
T|How do checksums, CRCs and MACs differ?|Checksums/CRCs target accidental corruption with different detection properties; a keyed MAC authenticates integrity under cryptographic assumptions.|A hostile sender can recompute an unkeyed CRC. Confidentiality is another property. Choose security primitives from a reviewed threat model, not a custom CRC-plus-secret scheme.|CRC is encryption.|What key lifecycle does a MAC require?|Correct integrity/authentication/confidentiality boundaries.
D|A command is valid but dangerously stale. Where enforce freshness?|At the authority boundary using a bounded lease/session/sequence policy in the receiving control domain.|Linux timestamps alone may not align with MCU time. Define clock/age assumptions and use receiver monotonic time for lease expiry. Reset must not renew an old queued command inadvertently.|Check CRC and assume newest packet is current.|How do you handle sequence wrap and clock reset?|Freshness independent of packet validity and defined reset behavior.
''')

add('Buildroot, Yocto and reproducibility','EL/KD','M10','R02; R04; R25; R34','Buildroot and Yocto are separate pinned lineages; future image builds unverified.',r'''
T|Compare Buildroot and Yocto for a product.|Both can produce embedded Linux systems, with different configuration/metadata/package workflows and integration costs.|Choose from team expertise, BSP ecosystem, customization, package/update strategy and maintenance needs. Do not equate a quick first build with lower lifetime product cost.|Yocto is a Linux distribution identical for every board.|Which artifacts would you preserve to reproduce an image?|Requirements-based comparison and lifecycle tradeoffs.
T|What is a Buildroot external tree?|It keeps product configuration, packages and board customization outside the upstream Buildroot source tree under its supported integration mechanism.|Store defconfig and relevant kernel/rootfs/package inputs, not only a generated output directory. Check the selected release's layout/hooks; moving manual examples are not a pin.|Copy random files into output/target and call it reproducible.|When can an incremental rebuild be misleading?|Declarative customization and clean-build evidence.
C|Describe the minimum complete custom application package.|Declare source/version/hash/license, build/install steps and configuration integration, with explicit dependencies.|For local educational sources, record a versioned immutable input and license. Install only required runtime artifacts and include startup policy separately. Build success must be followed by guest/service tests.|A shell command copying a host binary is a target package.|How do you prove the binary uses the target ABI?|Complete source-to-target integration and licensing traceability.
T|What is a Yocto layer, recipe, package and image?|A layer organizes metadata; a recipe describes build tasks; packages contain outputs; an image selects/install outputs into a target filesystem.|One recipe can produce multiple packages. Layers are not automatically runtime files, and adding a recipe does not necessarily install its package in an image.|Every layer becomes a partition on the device.|How does a bbappend alter an existing recipe?|Correct metadata/build/runtime boundaries.
D|A recipe builds but the target service cannot start. What inspect?|Check installed package content, runtime dependencies, interpreter/loader, service configuration, permissions and selected image inclusion.|DEPENDS and runtime dependency declarations solve different edges. Inspect actual rootfs/package metadata and service logs rather than adding host packages.|BitBake success proves runtime completeness.|What if a script needs an undeclared interpreter?|Runtime artifact/dependency diagnosis.
T|What is the SDK used for?|It supplies a compatible target toolchain/sysroot and environment for application development against the selected image context.|Record SDK/image lineage. An arbitrary compiler with a matching CPU name may still use incompatible libc/ABI or libraries. Validate an SDK-built client on the target.|Any AArch64 compiler is equivalent.|How do you distribute updated headers/libraries to application developers?|Coherent compiler/sysroot/image relationship.
D|An image changes despite unchanged application source. Why?|Inputs include layers/revisions, configs, downloaded sources, tools and nondeterministic metadata; caches can also hide undeclared dependencies.|Preserve manifests and compare artifacts with a controlled clean rebuild. A reproducible configuration is a prerequisite, not proof of byte-for-byte reproducible output.|The source commit alone completely defines every image.|How do timestamps/build paths affect reproducibility?|Complete input model and measured comparison.
T|What does sstate or a build cache guarantee?|It can reuse matching task outputs under the tool's dependency model, accelerating builds; it is not itself proof of reproducibility or correctness.|Trust boundaries, undeclared inputs and cache corruption still matter. Rebuild a small controlled comparison when investigating differences; do not routinely erase all caches without a hypothesis.|A cache hit proves the output matches an independent clean build.|How would you test a suspected undeclared dependency?|Cache model versus independent verification.
T|What belongs in license and SBOM evidence?|Actual shipped components/versions and license/dependency metadata, with source/notice obligations reviewed for the distribution context.|An SBOM helps inventory and vulnerability analysis but does not prove a product is secure or legally compliant. Keep generated records tied to the shipped image hash.|A license scanner or SPDX file settles every obligation.|How do local patches and bundled dependencies affect records?|Artifact-linked inventory and accurate limits.
D|A clean image build runs out of memory. What change first?|Confirm OOM evidence, host requirements, free memory/swap and parallelism; reduce concurrent tasks rather than changing application logic.|Record build configuration and resource conditions. Disk exhaustion and compiler errors can look similar in a truncated log; inspect the first real failure.|Retry with maximum parallelism for speed.|How do you estimate disk/cache needs before Yocto?|Measured resource diagnosis and controlled build settings.
''')

add('Debugging, tracing and performance','All','M14','R07; R08; R19; R33','Tool/target/configuration support varies; no performance measurements are supplied.',r'''
T|How choose GDB, strace, perf or ftrace?|Choose by the boundary: program state, syscall behavior, sampled performance or kernel execution/latency events.|Start from a hypothesis and needed observation, then account for overhead and permissions. A tool's availability does not make its output causal evidence.|Always run every tool at once.|Which tool would distinguish blocked I/O from CPU looping?|Question-to-observation mapping and limitations.
D|A crash stack points inside libc. How investigate?|Use matching symbols/core/binary, inspect callers and corrupted arguments, and consider earlier memory corruption.|The crash site may be a victim. Reproduce under supported sanitizers, minimize input and compare object lifetimes; don't blame a library from one frame.|The top frame is always the root cause.|What if optimization inlines or removes frames?|Artifact identity and cause-versus-symptom reasoning.
C|Build a reproducible latency measurement harness.|Define start/end events, monotonic timestamps, workload/load/seed, warmup, repetitions and raw output schema before measuring.|Report distribution, sample count, duration and observer overhead. Separate queue delay from service time. A script computing a percentile cannot create unrecorded target observations.|Publish one best run as worst-case latency.|How would you detect timestamp-domain mismatch?|Reproducible data collection and valid event definition.
T|What do ASan, UBSan and race tools miss?|They detect selected runtime classes in exercised paths/configurations; they do not prove algorithms, all UB, deadlines or all concurrency schedules correct.|Separate tool support and test coverage. Memory and race sanitizers may require separate builds. Keep a reasoning argument and meaningful tests alongside instrumentation.|No sanitizer report means the program is correct.|Can a clean run establish thread safety?|Qualified evidence and complementary verification.
D|CPU utilization is high but throughput low. What investigate?|Separate useful work, spinning, retries, lock contention, scheduling and I/O with profiles plus state/queue observations.|A hot retry loop may come from a zero timeout or persistent EAGAIN. A hotspot is an observation; change one cause and repeat comparable tests.|Optimize the longest function without checking workload.|How do you test the proposed bottleneck causally?|Hypothesis, discriminating experiment and before/after evidence.
D|An apparent memory leak grows only under backlog. What test?|Observe queue depth, retained ownership, allocator behavior and memory after draining under a controlled workload.|Bounded caching/backpressure differs from a leak. Track objects through allocation/queue/consume/free and test repeated load/drain cycles. RSS alone is insufficient.|Any nondecreasing RSS proves leaked allocations.|How would a fixed-capacity queue change diagnosis?|Object-lifetime accounting and steady-state evidence.
T|How interpret a kernel oops responsibly?|Preserve full logs, kernel/build/config/module identity and trace context; symbolize against the exact artifacts and form hypotheses.|An oops can follow prior corruption. Tainted/out-of-tree modules and missing symbols limit conclusions. A panic is not merely another application exception.|The last printk identifies the faulty source line.|Which additional fault/address data matters on your architecture?|Complete evidence and uncertainty-aware diagnosis.
D|A latency improvement appears only in one run. Can you claim it?|No; repeat controlled trials, report variability and check workload/load/config/measurement differences.|Compare distributions and costs, not only averages or a single tail percentile. If the effect is below variation, say evidence is inconclusive; preserve raw samples.|Any lower p99 proves the patch is better.|What regression workload should you add?|Statistically cautious, reproducible comparative reasoning.
T|How do KASAN and KCSAN relate to userspace sanitizers?|They target supported kernel memory/race diagnostics and require appropriate kernel/toolchain/configuration support.|Use a disposable guest and record config/overhead. They are not enabled by adding userspace -fsanitize flags to a driver build. Confirm architecture support before prescribing a run.|Every kernel/board can run all sanitizers simultaneously.|How might instrumentation affect timing experiments?|Layer/config support and separate diagnostic/performance claims.
D|Intermittent failure disappears after adding logs. What do you do?|Assume observation changed timing/state; retain minimal logging, use targeted traces and construct a deterministic fault/interleaving fixture.|Capture sequence IDs/timestamps or an event buffer where appropriate; distinguish log loss from actual event loss. Do not treat disappearance as a fix.|Keep massive logging and mark the race resolved.|How do you show a synchronization fix is correct?|Observer-effect awareness and an independent regression argument.
''')

add('Persistence, security, updates and maintenance','EL/KD','M15','R16; R21; R34','Threat/storage/boot guarantees must be stated; A03 implementation remains pending.',r'''
T|How replace persistent configuration robustly?|Validate, write a new file in the intended filesystem, synchronize as required, atomically rename and synchronize the directory under the selected storage contract.|Preserve last-known-good schema/version recovery. Atomic visibility and power-loss durability are different; test interruption at each transition on selected filesystem/storage.|Rename alone guarantees durability against all power failures.|How do disk-full and permission errors affect the active config?|Explicit visibility/durability/recovery distinction.
D|Power loss leaves a zero-length config. What investigate?|Inspect whether the active file was truncated before replacement, write/fsync errors were ignored or metadata durability was assumed.|Reproduce with a disposable fixture and inject interruption at each write/rename/sync state. Validate old/new records at boot; never silently treat corrupt data as valid defaults without policy.|Add a checksum and keep the same truncation path.|How would you retain the previous valid generation?|State-transition diagnosis and recoverable replacement design.
T|What does signing an update guarantee?|It can authenticate integrity/origin under the chosen key/trust policy; it does not prove the software is healthy, safe or non-vulnerable.|Validate target compatibility and key trust before activation, then health-check a candidate. Keep private signing keys off target and out of repositories.|Signed software is automatically secure and cannot fail boot.|What happens if the signing key is compromised?|Cryptographic boundary plus operational/key-lifecycle limits.
T|How does A/B rollback work?|Install into an inactive slot, mark a candidate with bounded boot attempts, and commit only after health criteria; otherwise boot the known-good slot.|Boot state must survive resets consistently. An updater alone cannot guarantee rollback if the bootloader never consumes attempt state or falls back. Test every interrupted transition.|Two partitions and a signed copy automatically provide rollback.|Who marks the new slot good and when?|Durable boot-attempt/health state and actual boot integration.
D|An image is signed but for another product. What must happen?|Reject it based on authenticated compatibility metadata before activation or writing incompatible critical state.|Signatures answer who approved bytes, not whether these bytes fit this hardware/schema. Keep product/board/storage compatibility explicit and tested.|Accept anything signed by the organization's key.|How do configuration migrations interact with rollback?|Compatibility and downgrade/migration policy.
C|Design a health gate before committing an update.|Require bounded successful boot plus essential service/data progress checks, then record success durably; failure leaves fallback available.|A running PID alone can mask deadlock or stale sensors. Define timeout and minimum checks from product requirements, and test false positives/false negatives.|Mark good immediately when the kernel starts.|What if the health service itself crashes?|Meaningful bounded health and fallback ownership.
T|How do secure boot, verified filesystems and signed updates differ?|They protect different parts of a trust chain: booted code, runtime content verification and accepted installation artifacts under their chosen policies.|Specify roots of trust, keys and rollback policy. A signed bundle does not automatically enforce boot verification; a verified rootfs does not validate mutable configuration semantics.|They are interchangeable names for encryption.|Where does anti-rollback state live?|Distinct trust stages and explicit integration assumptions.
T|What is least privilege for an embedded service?|Give only required identities, device/file access and capabilities, with isolation supported by the selected image/runtime.|Avoid root by default where feasible; separate update authority from telemetry parsing. Test denied access and preserve recovery observability. Security claims require an actual configuration review.|Run everything as root because the device is single-user.|How does hardware device access constrain sandboxing?|Concrete resource permissions and tested failure behavior.
D|An SBOM reports an old component version. What next?|Identify the shipped artifact, patch/backport status, reachable use and relevant advisories before deciding remediation and retest scope.|Inventory is the start, not a vulnerability verdict. Record evidence and maintain an update plan; do not infer safety solely from a vendor version string or scanner score.|An SBOM means no vulnerable dependencies exist.|How do local patches affect version interpretation?|Artifact/advisory/backport traceability without unsupported security claims.
T|What should a product maintenance plan contain?|Supported versions, dependency/security review, regression tests, key/update policy, fleet observability, recovery and end-of-support responsibilities.|A reproducible initial image does not maintain itself. Retain source/config/license/build evidence and rehearse restoration; test migrations with rollback constraints.|Ship once and freeze forever because changes cause bugs.|Which obligations remain after a field update fails?|Lifecycle ownership and recoverable update strategy.
''')

add('System design and project defense','All','M16','C01/C02 requirements; R16; R24; R33','Design targets are assumptions to validate, not measured results or production safety certification.',r'''
S|Design a one-path industrial monitoring gateway.|Clarify rate/size/storage/update needs; separate serial acquisition, bounded storage, config, health and signed-image recovery with explicit owners.|Use C01's 10 Hz stream as an assumed workload. Derive queue/log bounds from stall/retention budgets; test bad frames, disconnect, disk full and interrupted updates. Do not add cloud complexity before core acceptance.|Draw boxes without failure, persistence or recovery semantics.|How would you prove a stale sensor is observable?|Requirements→interfaces→bounds→fault tests traceability.
S|Design a Linux service supervising several device tasks.|Use bounded interfaces and a supervisor health policy that distinguishes process existence, useful data progress and recoverable failures.|Choose process/thread isolation from fault boundaries; define restart/backoff, stale-data marking and persistent state. A restart loop needs bounds and diagnostic preservation.|Restart everything immediately for every error.|What state must survive a restart?|Lifecycle, health and overload policy with observable recovery.
S|Design a sensor acquisition driver interface.|Choose an existing fitting subsystem, define channels/units/buffering/timestamps and expose errors/power transitions consistently.|For an accelerometer consider IIO and existing support first. Draw bus/IRQ/worker/user paths with contexts and teardown dependencies; test invalid configuration, bus faults and unbind.|Expose raw internal pointers through a custom ioctl.|How would direct mode and buffered mode interact?|Subsystem fit, ABI, context and lifetime design.
S|Design a safe field-update workflow for a gateway.|Separate signing authority, compatibility verification, inactive-slot installation, durable boot attempts and useful health confirmation.|Specify rollback, key rotation/revocation, schema migration and recovery if metadata or power fails. Test rejected bundles and every interruption boundary on disposable disks.|Treat HTTPS download as sufficient authenticity and rollback.|How can a data migration prevent rollback?|Trust/persistence/boot/health integration and concrete fault matrix.
S|Design a low-latency Linux telemetry pipeline.|Specify event-to-consumer deadline, rates/bursts and queue policy; assign owners and measure each stage under representative load.|Bound allocation/logging in critical paths and locate contention with traces. Separate empirical max from a proven timing bound; compare changes with raw repeated measurements.|Raise all priorities and claim hard real time.|Which work belongs outside the latency path?|Budgeted stages, overload behavior and credible measurement plan.
S|Design Linux–MCU robot control responsibilities.|Linux handles planning/diagnostics; MCU owns periodic control, command lease, output bounds and local fault transition.|Start C02 with deterministic plant simulation. Define session/sequence, receiver-time freshness, sensor stall and reset behavior. Zero command in simulation does not prove physical stopping safety.|Linux sends PWM continuously and MCU follows forever if link dies.|How would you add an independent emergency stop later?|Authority/timing/fault boundaries and explicit physical gaps.
S|Design diagnostic anomaly inference without disturbing control.|Keep a deterministic baseline, session-separated dataset and lower-priority bounded-age inference output outside the control deadline.|Evaluate false alarms/missed faults/delay and resource cost on held-out sessions. Fall back when score/model is unavailable or late; record no invented benchmarks.|Put a neural network directly in the hard IRQ control path.|How do you prevent overlapping-window leakage?|Data/evaluation/resource/fallback design and preserved control contract.
S|Design shared DMA buffer ownership for acquisition.|Define CPU/device ownership transitions, mapping/direction/sync rules, completion and shutdown before selecting a zero-copy interface.|Address domains, cache-line sharing and userspace lifetime require explicit handling. Start from supported subsystem APIs; test cancellation, reset and completion after close. Zero-copy is a tradeoff, not an initial goal.|Share one raw pointer between userspace and hardware with no reference management.|How does an IOMMU change addressing but not lifetime?|End-to-end mapping/ownership/reclamation timeline.
S|Design an automated embedded CI test ladder.|Use host logic/model tests, target cross-build/static checks, isolated emulator integration and separately scheduled hardware tests.|Tie each result to source/config/tool/image identity; distinguish authored/built/run and never promote a simulated pass to electrical/timing validation. Retain failure artifacts and minimal reproducers.|A host unit-test pass means the entire board image is validated.|Which faults can only be verified on hardware?|Layered evidence, meaningful tests and truthful scope.
S|Defend a capstone and plan its next production step.|State actual requirements, your contribution, architecture, one reproduced failure, real test evidence and limitations; prioritize the highest-risk unverified assumption.|Use actual reports for numbers. For C02 disclose simulated plant, missing physical timing/e-stop/hazard analysis. Supplied reference code is not your industry experience; choose a concrete next experiment.|Invent uptime/performance numbers and claim production readiness.|Which design choice would you change with a tighter budget?|Honest ownership, evidence-backed tradeoff and actionable next validation.
''')

assert len(groups)==20
questions=[]
kind_names={'T':'conceptual','C':'coding','D':'debugging/scenario','O':'code-output analysis','S':'system design'}
intro='''# Interview bank — 200 distinct questions with answers

This bank is delivered for all three tracks. It is interview practice, not a substitute for the still-pending full lessons and project implementations. Primary-source IDs resolve in ../09_References_and_Resources/REFERENCES.md. Concept and design answers use stated assumptions; target API signatures must be checked in the selected source before implementation. No company-specific interview pattern or experience claim is asserted.

**Scoring for every question:** 0 = unsafe/incorrect or invented evidence; 1 = recognizes terminology but misses the contract; 2 = gives the core spoken answer with key assumptions; 3 = explains the deeper example and avoids the named pitfall; 4 = also satisfies the question-specific discriminator, handles the follow-up, and proposes a meaningful boundary/failure test. A memory-safety/context/security critical error blocks passage regardless of average. Use changed input for a retention attempt. Coding answers describe complete algorithm/contracts; only code explicitly delivered in project/solution files is a compiled reference implementation. Do not treat design outlines as executed code.

Use questions_only.md for attempts, then open a topic answer file. Difficulty and round are practice organization, not employer claims. Module links for undelivered lessons lead to a status catalog.

'''
for topic_index,(topic,track,module,refs,assumptions,items) in enumerate(groups):
    first=topic_index*10+1
    filename=f'{first:03d}_{first+9:03d}_'+topic.replace(' ','_').replace(',','').replace('/','_').replace('–','_')+'.md'
    content=f'# {topic}\n\n'
    for offset,(kind,prompt,spoken,deep,wrong,follow,criterion) in enumerate(items):
        n=first+offset
        qid=f'Q{n:03d}'
        difficulty='foundation' if n<=70 else ('advanced' if kind=='S' or n>=181 else 'intermediate')
        round_name={'T':'technical screen','C':'coding practical','D':'debugging/code review','O':'technical screen','S':'design/project defense'}[kind]
        catalog_module=module.split('/')[0]
        learning=f'../03_JD_JR_Skills_and_Learning_Content/MODULE_CATALOG.md#{catalog_module.lower()}'
        q={'ID':qid,'Topic':topic,'Track':track,'Difficulty':difficulty,'Round':round_name,'Category':kind_names[kind],
           'Question':prompt,'Assessed skill':criterion,'Spoken answer':spoken,'Deeper explanation/example':deep,
           'Assumptions/version':assumptions,'Common incorrect answer':wrong,'Follow-up':follow,
           'Full-credit discriminator':criterion,'Learning module':module,'Learning link':learning,'References':refs}
        questions.append(q)
        content+=f'''## {qid} — {prompt}

**Tags:** {track}; {difficulty}; {round_name}; {kind_names[kind]}. **Assesses:** {criterion}

**Spoken answer:** {spoken}

**Deeper explanation/example:** {deep}

**Assumptions/version:** {assumptions}

**Common incorrect answer:** {wrong}

**Follow-up:** {follow}

**Scoring:** use the bank's 0–4 rubric; full credit specifically requires: {criterion} [Learning: {module}]({learning}). References: {refs}.

'''
    write('02_Interview_Questions_and_Answers/'+filename,content)
    intro+=f'- [{first:03d}–{first+9:03d}: {topic}]({filename}) — {track}; {module}.\n'
assert len(questions)==200
counts={label:sum(q['Category']==label for q in questions) for label in kind_names.values()}
assert counts['coding']>=25 and counts['debugging/scenario']>=25 and counts['system design']>=10
intro+='\nActual category counts (each question has one primary category): '+', '.join(f'{k}: {v}' for k,v in counts.items())+'. Some coding/design questions also contain debugging scenarios, but those overlaps are not counted twice.\n'
write('02_Interview_Questions_and_Answers/README.md',intro)
write('02_Interview_Questions_and_Answers/questions_only.md','# Interview attempts — questions only\n\nUse 2–4 minutes for a conceptual answer, 15–45 minutes for a coding task and 20–40 minutes for a design depending on scope. State assumptions and tool/AI rules before starting. Scored reference solutions for every coding implementation remain a separate future deliverable; the bank provides spoken/deeper reference answers.\n\n'+'\n\n'.join(f"## {q['ID']} — {q['Question']}\n\n{q['Track']}; {q['Difficulty']}; {q['Round']}; {q['Category']}." for q in questions))
table('02_Interview_Questions_and_Answers/question_index.csv',[{key:q[key] for key in ['ID','Topic','Track','Difficulty','Round','Category','Question','Learning module','References']} for q in questions])
write('02_Interview_Questions_and_Answers/bank.json',json.dumps(questions,ensure_ascii=False,indent=2))
write('02_Interview_Questions_and_Answers/category_counts.json',json.dumps(counts,indent=2))

if __name__=='__main__':print(json.dumps({'questions':len(questions),'categories':counts},indent=2))
